using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Shared configuration for evaluation runs: telemetry, quality evaluators, and comparison storage.
/// </summary>
public static class EvalSetup
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "results");

    /// <summary>
    /// Builds a TracerProvider that exports AI-related spans to the console and OTLP endpoint.
    /// </summary>
    public static TracerProvider CreateTelemetryProvider()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Eval"))
            .AddSource("Microsoft.Extensions.AI")
            .AddSource("MyApp.*")
            .AddConsoleExporter()
            .AddOtlpExporter()
            .Build()!;
    }

    /// <summary>
    /// Returns the standard quality evaluators (excludes safety).
    /// </summary>
    public static IList<IEvaluator> GetQualityEvaluators(IChatClient judgeChatClient)
    {
        return new List<IEvaluator>
        {
            new RelevanceEvaluator(judgeChatClient),
            new CoherenceEvaluator(judgeChatClient),
            new FluencyEvaluator(judgeChatClient),
            new GroundednessEvaluator(judgeChatClient),
            new CompletenessEvaluator(judgeChatClient),
        };
    }

    /// <summary>
    /// Creates a ReportingConfiguration wired for disk-based storage so results
    /// can be compared across runs.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(
        IChatClient chatClient,
        IChatClient judgeChatClient,
        string scenarioName)
    {
        var storage = new DiskBasedResultStorage(StoragePath);

        return new ReportingConfiguration(
            chatClient,
            GetQualityEvaluators(judgeChatClient),
            resultStorage: storage,
            scenarioName: scenarioName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that AI interactions produce the expected OTel spans.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task ChatCompletion_EmitsTraceSpans()
    {
        using var tracerProvider = EvalSetup.CreateTelemetryProvider();

        var chatClient = CreateChatClient();
        var response = await chatClient.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
        // Spans are exported via the configured exporters (console + OTLP).
    }

    [TestMethod]
    public async Task StreamingCompletion_EmitsTraceSpans()
    {
        using var tracerProvider = EvalSetup.CreateTelemetryProvider();

        var chatClient = CreateChatClient();
        var chunks = new List<string>();

        await foreach (var update in chatClient.GetStreamingResponseAsync("Tell me a joke."))
        {
            if (update.Text is not null)
                chunks.Add(update.Text);
        }

        Assert.IsTrue(chunks.Count > 0);
    }

    private static IChatClient CreateChatClient()
    {
        // Uses AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY");

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(apiKey))
            .AsChatClient("gpt-4o-mini");
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: runs evaluators (relevance, coherence, fluency, groundedness, completeness)
/// against the coach agent responses.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IChatClient ChatClient => CreateChatClient();
    private static IChatClient JudgeClient => CreateChatClient();

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        var reportingConfig = EvalSetup.CreateReportingConfig(
            ChatClient, JudgeClient, scenarioName: nameof(CoachResponse_MeetsQualityBar));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How can I improve my morning routine to be more productive?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        // Run quality evaluators and assert no failures.
        var evaluationResult = await scenario.EvaluateAsync(messages, response);
        AssertNoFailures(evaluationResult);
    }

    [TestMethod]
    public async Task CoachResponse_StaysOnTopic()
    {
        var reportingConfig = EvalSetup.CreateReportingConfig(
            ChatClient, JudgeClient, scenarioName: nameof(CoachResponse_StaysOnTopic));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach. Only answer productivity questions."),
            new(ChatRole.User, "Give me tips for managing my task backlog effectively.")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);
        AssertNoFailures(evaluationResult);
    }

    private static void AssertNoFailures(EvaluationResult result)
    {
        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(
                metric.Value.Interpretation?.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{metric.Key}' returned inconclusive.");
            Assert.AreNotEqual(
                EvaluationRating.Unacceptable,
                metric.Value.Interpretation?.Rating,
                $"Evaluator '{metric.Key}' rated response as unacceptable.");
        }
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY");

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(apiKey))
            .AsChatClient("gpt-4o-mini");
    }
}

