namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs scenarios and stores results so they can be diffed across runs.
/// Use `dotnet eval compare` or the reporting HTML to view regressions.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "results");

    [TestMethod]
    public async Task Baseline_CompareAcrossRuns()
    {
        var chatClient = CreateChatClient();
        var judgeClient = CreateChatClient();

        var storage = new DiskBasedResultStorage(StoragePath);

        var reportingConfig = new ReportingConfiguration(
            chatClient,
            EvalSetup.GetQualityEvaluators(judgeClient),
