            new CoherenceEvaluator(judgeChatClient),
            new FluencyEvaluator(judgeChatClient),
            new GroundednessEvaluator(judgeChatClient),
            new CompletenessEvaluator(judgeChatClient),
        };
    }

    /// <summary>
    /// Creates a ReportingConfiguration wired for disk-based storage so results
    /// can be compared across runs.
    /// </summary>
