using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: runs evaluators (relevance, coherence, fluency, groundedness, completeness)
/// against the coach agent responses.
/// </summary>
[TestClass]
public class QualityTests
{
    private static IChatClient ChatClient => CreateChatClient();
    private static IChatClient JudgeClient => CreateChatClient();

    [TestMethod]
    public async Task CoachResponse_MeetsQualityBar()
    {
        var reportingConfig = EvalSetup.CreateReportingConfig(
            ChatClient, JudgeClient, scenarioName: nameof(CoachResponse_MeetsQualityBar));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How can I improve my morning routine to be more productive?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);
        AssertNoFailures(evaluationResult);
    }

    [TestMethod]
    public async Task CoachResponse_StaysOnTopic()
    {
        var reportingConfig = EvalSetup.CreateReportingConfig(
            ChatClient, JudgeClient, scenarioName: nameof(CoachResponse_StaysOnTopic));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a productivity coach. Only answer productivity questions."),
            new(ChatRole.User, "Give me tips for managing my task backlog effectively.")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);
        AssertNoFailures(evaluationResult);
    }

    private static void AssertNoFailures(EvaluationResult result)
    {
        foreach (var metric in result.Metrics)
        {
            Assert.IsFalse(
                metric.Value.Interpretation?.Rating == EvaluationRating.Inconclusive,
                $"Evaluator '{metric.Key}' returned inconclusive.");
            Assert.AreNotEqual(
                EvaluationRating.Unacceptable,
                metric.Value.Interpretation?.Rating,
                $"Evaluator '{metric.Key}' rated response as unacceptable.");
        }
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY");

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(apiKey))
            .AsChatClient("gpt-4o-mini");
    }
}

