using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Compare mode: runs scenarios and stores results so they can be diffed across runs.
/// Use the reporting output to view regressions between baseline and current.
/// </summary>
[TestClass]
public class CompareTests
{
    private static readonly string StoragePath =
        Path.Combine(Path.GetTempPath(), "MyApp.Eval", "results");

    [TestMethod]
    public async Task Baseline_CompareAcrossRuns()
    {
        var chatClient = CreateChatClient();
        var judgeClient = CreateChatClient();

        var storage = new DiskBasedResultStorage(StoragePath);

        var reportingConfig = new ReportingConfiguration(
            chatClient,
            EvalSetup.GetQualityEvaluators(judgeClient),
            resultStorage: storage,
            scenarioName: "baseline-compare");

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are three evidence-based strategies for better focus?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);

        Assert.IsTrue(evaluationResult.Metrics.Count > 0,
            "Expected at least one metric to be recorded for comparison.");
    }

    [TestMethod]
    public async Task PromptVariant_CompareAcrossRuns()
    {
        var chatClient = CreateChatClient();
        var judgeClient = CreateChatClient();

        var storage = new DiskBasedResultStorage(StoragePath);

        var reportingConfig = new ReportingConfiguration(
            chatClient,
            EvalSetup.GetQualityEvaluators(judgeClient),
            resultStorage: storage,
            scenarioName: "prompt-variant-compare");

        await using var scenario = await reportingConfig.CreateScenarioRunAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a concise productivity coach. Answer in at most 3 bullet points."),
            new(ChatRole.User, "What are three evidence-based strategies for better focus?")
        };

        var response = await scenario.ChatClient!.GetResponseAsync(messages);
        Assert.IsNotNull(response);

        var evaluationResult = await scenario.EvaluateAsync(messages, response);

        Assert.IsTrue(evaluationResult.Metrics.Count > 0,
            "Expected at least one metric to be recorded for comparison.");
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY");

        return new Azure.AI.Inference.ChatCompletionsClient(
                new Uri(endpoint),
                new Azure.AzureKeyCredential(apiKey))
            .AsChatClient("gpt-4o-mini");
    }
}

